    function run(uint256 amount, address observed) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;

